/**
 * Coordinator - Intent selector with hysteresis
 *
 * Manages intent selection for an AI agent. Selects the highest-priority
 * activatable intent while applying hysteresis to prevent rapid switching.
 *
 * **Features**
 *
 * - Priority-based selection
 * - Hysteresis threshold to prevent thrashing
 * - Minimum dwell time per intent
 * - Variadic add/remove API
 *
 * **Usage**
 *
 * ```js
 * const coordinator = new Coordinator({ hysteresisThreshold: 10 });
 *
 * // Add intents
 * coordinator.add(
 *   new PatrolIntent({ priority: 20 }),
 *   new EngageIntent({ priority: 80 })
 * );
 *
 * // Update each frame
 * const agentIntent = coordinator.update(body, state, memory, delta);
 * ```
 *
 * @module @three-blocks/pro/ai/Coordinator
 * @class Coordinator
 * @short Intent selector with hysteresis
 * @category AI
 * @private
 * @tags AI, Intent, Coordinator, Decision
 */
export class Coordinator {
    /**
     * Create a new Coordinator.
     *
     * @param {Object} [config] - Configuration options.
     * @param {number} [config.hysteresisThreshold=10] - Priority difference needed to switch.
     */
    constructor(config?: {
        hysteresisThreshold?: number;
    });
    /**
     * Priority difference needed to force a switch.
     * @type {number}
     * @private
     */
    private _hysteresisThreshold;
    /**
     * Array of managed intents.
     * @type {Intent[]}
     * @private
     */
    private _intents;
    /**
     * Map of intents by ID for fast lookup.
     * @type {Map<string, Intent>}
     * @private
     */
    private _intentMap;
    /**
     * Currently active intent.
     * @type {Intent|null}
     * @private
     */
    private _activeIntent;
    /**
     * Time the active intent has been running.
     * @type {number}
     * @private
     */
    private _activeIntentTime;
    /**
     * Cached idle intent for when nothing can activate.
     * @type {AgentIntent}
     * @private
     */
    private _idleIntent;
    /**
     * Agent context for event emission.
     * Set by AIController when coordinator is attached.
     * @type {Object|null}
     * @private
     */
    private _agentContext;
    /**
     * Add one or more intents.
     *
     * @param {...Intent} intents - Intents to add.
     * @returns {Coordinator} This instance for chaining.
     */
    add(...intents: Intent[]): Coordinator;
    /**
     * Remove an intent.
     *
     * @param {Intent} intent - Intent to remove.
     * @returns {boolean} True if intent was removed.
     */
    remove(intent: Intent): boolean;
    /**
     * Remove an intent by ID.
     *
     * @param {string} id - Intent ID to remove.
     * @returns {boolean} True if intent was removed.
     */
    removeById(id: string): boolean;
    /**
     * Get an intent by ID.
     *
     * @param {string} id - Intent ID.
     * @returns {Intent|undefined} The intent or undefined.
     */
    get(id: string): Intent | undefined;
    /**
     * Get an intent by type.
     *
     * @param {string} type - Intent type.
     * @returns {Intent|undefined} First intent of type or undefined.
     */
    getByType(type: string): Intent | undefined;
    /**
     * Get currently active intent.
     *
     * @returns {Intent|null} The active intent or null.
     */
    get activeIntent(): Intent | null;
    /**
     * Get name of currently active intent.
     *
     * @returns {string} The active intent type or 'idle'.
     */
    get activeIntentName(): string;
    /**
     * Update coordinator and return action instructions.
     *
     * @param {Object} body - The physics body.
     * @param {State} state - Current perception state.
     * @param {Memory} memory - Time-decaying memory.
     * @param {number} delta - Time delta in seconds.
     * @returns {AgentIntent} Action instructions.
     */
    update(body: any, state: State, memory: Memory, delta: number): AgentIntent;
    /**
     * Check if we should switch to a new intent.
     *
     * @param {Intent} candidate - The candidate intent.
     * @param {State} state - Current perception state.
     * @param {Memory} memory - Time-decaying memory.
     * @returns {boolean} True if should switch.
     * @private
     */
    private _shouldSwitch;
    /**
     * Switch to a new intent.
     *
     * @param {Intent|null} newIntent - The new intent or null for idle.
     * @param {State} state - Current perception state.
     * @param {Memory} memory - Time-decaying memory.
     * @private
     */
    private _switchIntent;
    /**
     * Force switch to a specific intent.
     *
     * @param {Intent|string} intentOrId - Intent or ID to switch to.
     * @param {State} state - Current perception state.
     * @param {Memory} memory - Time-decaying memory.
     * @returns {boolean} True if switch was successful.
     */
    forceSwitch(intentOrId: Intent | string, state: State, memory: Memory): boolean;
    /**
     * Get the number of intents.
     *
     * @returns {number} Number of intents.
     */
    get count(): number;
    /**
     * Get all intents.
     *
     * @returns {Intent[]} Array of all intents.
     */
    get intents(): Intent[];
    /**
     * Serialize all intents for worker transfer.
     *
     * @returns {Object[]} Array of serialized intent configs.
     */
    serialize(): any[];
    /**
     * Configure coordinator parameters.
     *
     * @param {Object} config - Configuration object.
     * @returns {Coordinator} This instance for chaining.
     */
    set(config: any): Coordinator;
    /**
     * Clear all intents.
     *
     * @returns {Coordinator} This instance for chaining.
     */
    clear(): Coordinator;
    /**
     * Dispose of all intents and clear.
     */
    dispose(): void;
}
import { AgentIntent } from './AgentIntent.js';
